//! The responsibility substrate: coverage by RESPONSIBILITY rather than by file.
//!
//! The matrix is generated from the registry and frontmatter on every call — a
//! hand-maintained map would lie about state. The committed view
//! (`.claude/harness-substrate.md`) is regenerated by the inventory script and
//! drift-checked here. Port of `core/substrate.ts`.
use std::path::Path;

use super::result::{CheckResult, Section, Status};
use super::substrate_aggregate::aggregate_substrate;
pub use super::substrate_view::render_substrate_view;

/// Canonical taxonomy: the 11 vendor-neutral responsibilities plus one
/// kit-specific addition. Order is display order; `core` marks the 11.
pub const TAXONOMY: [(&str, &str, bool); 12] = [
    ("task-specification", "Task specification", true),
    ("context-selection", "Context selection", true),
    ("tool-access", "Tool access", true),
    ("project-memory", "Project memory", true),
    ("task-state", "Task state", true),
    ("observability", "Observability", true),
    ("failure-attribution", "Failure attribution", true),
    ("verification", "Verification", true),
    ("permissions", "Permissions", true),
    ("entropy-auditing", "Entropy auditing", true),
    ("intervention-recording", "Intervention recording", true),
    ("gate-enforcement", "Gate enforcement", false),
];

const VIEW_PATH: &str = "harness-substrate.md";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Coverage {
    Covered,
    Partial,
    Missing,
}

impl Coverage {
    pub(super) fn icon(self) -> &'static str {
        match self {
            Coverage::Covered => "✅ covered",
            Coverage::Partial => "🟡 partial",
            Coverage::Missing => "⬜ missing",
        }
    }
}

pub struct ResponsibilityRow {
    pub value: &'static str,
    pub label: &'static str,
    pub core: bool,
    pub coverage: Coverage,
    pub count: usize,
    pub active: usize,
    pub examples: Vec<String>,
}

pub struct SubstrateAggregate {
    pub rows: Vec<ResponsibilityRow>,
    /// Artifacts whose responsibility is not in the taxonomy (always a problem).
    pub invalid: Vec<(String, String)>,
    /// Registry-sourced artifacts with no responsibility — a hard gap, because
    /// the registry is the seeded set.
    pub untagged_registry: Vec<String>,
    /// Frontmatter-sourced artifacts with none — allowed, tag-on-touch.
    pub untagged_frontmatter: Vec<String>,
    pub total_artifacts: usize,
}

/// The allowed responsibility values, from the embedded schema; the taxonomy is
/// the fallback when the schema has no enum.
pub fn responsibility_enum() -> Vec<String> {
    let from_schema = super::ownership_rows::schema_enum("responsibility");
    if !from_schema.is_empty() {
        return from_schema.into_iter().collect();
    }
    TAXONOMY
        .iter()
        .map(|(value, _, _)| (*value).to_string())
        .collect()
}

/// Validate the tagging plus the committed view's freshness. Registry untagged,
/// out-of-enum and stale-view are FAIL; frontmatter untagged is a WARN, because
/// tagging there is on-touch — reported, never hidden.
pub fn check_substrate(claude_dir: &Path, missing_view_severity: Status) -> Vec<CheckResult> {
    let aggregate = aggregate_substrate(claude_dir);
    let mut results = Vec::new();
    for (path, value) in &aggregate.invalid {
        results.push(CheckResult::new(
            format!("Substrate: {path}"),
            Status::Fail,
            format!("responsibility=\"{value}\" not in taxonomy enum"),
            Section::Substrate,
        ));
    }
    for path in &aggregate.untagged_registry {
        results.push(CheckResult::new(
            format!("Substrate: {path}"),
            Status::Fail,
            "registry artifact has no responsibility (seed it)",
            Section::Substrate,
        ));
    }
    if !aggregate.untagged_frontmatter.is_empty() {
        results.push(CheckResult::new(
            "Substrate: untagged frontmatter artifacts",
            Status::Warn,
            format!(
                "{} skill/agent artifact(s) untagged — tag-on-touch (allowed, reported).",
                aggregate.untagged_frontmatter.len()
            ),
            Section::Substrate,
        ));
    }

    let view_path = claude_dir.join(VIEW_PATH);
    let fresh = render_substrate_view(&aggregate);
    if !view_path.exists() {
        results.push(CheckResult::new(
            "Substrate view present",
            missing_view_severity,
            if missing_view_severity == Status::Warn {
                "No .claude/harness-substrate.md — run `MEWKIT_BLESS=1 cargo test -p mewkit-core --test bless_substrate_view`"
            } else {
                "Missing .claude/harness-substrate.md (run `MEWKIT_BLESS=1 cargo test -p mewkit-core --test bless_substrate_view`)"
            },
            Section::Substrate,
        ));
    } else {
        let committed = std::fs::read(&view_path)
            .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
            .unwrap_or_default();
        let in_sync = committed.trim() == fresh.trim();
        results.push(CheckResult::new(
            "Substrate view in sync",
            if in_sync { Status::Pass } else { Status::Fail },
            if in_sync {
                view_path.display().to_string()
            } else {
                "harness-substrate.md is stale — run `MEWKIT_BLESS=1 cargo test -p mewkit-core --test bless_substrate_view`".to_string()
            },
            Section::Substrate,
        ));
    }

    let fails = results
        .iter()
        .filter(|row| row.status == Status::Fail)
        .count();
    let covered = aggregate
        .rows
        .iter()
        .filter(|row| row.coverage == Coverage::Covered)
        .count();
    results.push(CheckResult::new(
        "Substrate coverage",
        if fails == 0 {
            Status::Pass
        } else {
            Status::Fail
        },
        if fails == 0 {
            format!(
                "{} artifacts; {covered}/{} responsibilities covered",
                aggregate.total_artifacts,
                aggregate.rows.len()
            )
        } else {
            format!("{fails} substrate issue(s)")
        },
        Section::Substrate,
    ));
    results
}

